#include "recovery/Recovery.h"
#include <chrono>
namespace forge::recovery {std::filesystem::path Recovery::snapshot(const std::filesystem::path&src,const std::string&label,std::string&err)const{try{auto dir=src/"Cache/Recovery";std::filesystem::create_directories(dir);auto t=std::chrono::system_clock::to_time_t(std::chrono::system_clock::now());auto out=dir/(label+"_"+std::to_string(t));std::filesystem::create_directories(out);for(auto&it:std::filesystem::directory_iterator(src)){if(it.path().filename()=="Cache"||it.path().filename()=="Builds")continue;if(it.is_regular_file())std::filesystem::copy_file(it.path(),out/it.path().filename(),std::filesystem::copy_options::overwrite_existing);}return out;}catch(const std::exception&e){err=e.what();return{};}}std::vector<std::filesystem::path> Recovery::list(const std::filesystem::path&p)const{std::vector<std::filesystem::path>v;auto d=p/"Cache/Recovery";if(std::filesystem::exists(d))for(auto&i:std::filesystem::directory_iterator(d))if(i.is_directory())v.push_back(i.path());return v;}}
